// The build's identity, generated by cmake/version.cmake on every build.
// The same fields are in the library's .note.parcagpu ELF note, which
// `readelf -n libparcagpucupti.so` shows without loading it.
#ifndef PARCAGPU_VERSION_H_
#define PARCAGPU_VERSION_H_

namespace parcagpu {

// git describe --always --dirty --tags (e.g. "v0.4.0-4-gabc1234-dirty"), or
// the PARCAGPU_VERSION build variable; "unknown" without either.
const char *buildVersion();

// The full git sha, or "unknown".
const char *buildSha();

// "1" if built from a tree with uncommitted changes to tracked files, "0" if
// not, "unknown" if that couldn't be told.
const char *buildDirty();

// CMAKE_BUILD_TYPE, e.g. "RelWithDebInfo".
const char *buildType();

// All of the above and the CUDA headers parcagpu was built against, as
// space-separated key=value pairs:
//   version=v0.4.0-4-gabc1234 sha=<40 hex> dirty=0 build_type=RelWithDebInfo
//   cuda_headers=12.8 cupti_api=24
// The keys are stable; new ones may be added at the end.
const char *buildInfo();

} // namespace parcagpu

#endif // PARCAGPU_VERSION_H_
